namespace TemporalioSamples.Tests.SearchAttributes;

using Temporalio.Common;
using Temporalio.Testing;
using Temporalio.Worker;
using TemporalioSamples.SearchAttributes;
using Xunit;
using Xunit.Abstractions;

public class SearchAttributesWorkflowTests : TestBase
{
    private static readonly string[] ExpectedKeywordListValues = { "value1", "value2" };

    public SearchAttributesWorkflowTests(ITestOutputHelper output)
        : base(output)
    {
    }

    [Fact]
    public async Task RunAsync_SearchAttributesWorkflow_UpsertsAndQueries()
    {
        // Start a dev server with the custom search attributes registered
        await using var env = await WorkflowEnvironment.StartLocalAsync(new()
        {
            SearchAttributes =
            [
                SearchAttributesWorkflow.CustomIntField,
                SearchAttributesWorkflow.CustomKeywordField,
                SearchAttributesWorkflow.CustomBoolField,
                SearchAttributesWorkflow.CustomDoubleField,
                SearchAttributesWorkflow.CustomDatetimeField,
                SearchAttributesWorkflow.CustomKeywordListField,
            ],
        });

        var taskQueue = $"tq-{Guid.NewGuid()}";
        using var worker = new TemporalWorker(
            env.Client,
            new TemporalWorkerOptions(taskQueue).
                AddAllActivities(new SearchAttributesActivities(env.Client)).
                AddWorkflow<SearchAttributesWorkflow>());
        await worker.ExecuteAsync(async () =>
        {
            // Run the workflow to completion. It reads the initial attribute, upserts more,
            // unsets one, and waits until it can find itself with a visibility query.
            var handle = await env.Client.StartWorkflowAsync(
                (SearchAttributesWorkflow wf) => wf.RunAsync(),
                new(id: $"search-attributes-{Guid.NewGuid()}", taskQueue: taskQueue)
                {
                    TypedSearchAttributes = new SearchAttributeCollection.Builder().
                        Set(SearchAttributesWorkflow.CustomIntField, 1).
                        ToSearchAttributeCollection(),
                });
            await handle.GetResultAsync();

            // Confirm the final search attribute values on the execution
            var description = await handle.DescribeAsync();
            var attributes = description.TypedSearchAttributes;
            Assert.Equal(2, attributes.Get(SearchAttributesWorkflow.CustomIntField));
            Assert.Equal("Keyword fields supports prefix search", attributes.Get(SearchAttributesWorkflow.CustomKeywordField));
            Assert.True(attributes.Get(SearchAttributesWorkflow.CustomBoolField));
            Assert.True(attributes.ContainsKey(SearchAttributesWorkflow.CustomDatetimeField));
            Assert.Equal(ExpectedKeywordListValues, attributes.Get(SearchAttributesWorkflow.CustomKeywordListField));

            // CustomDoubleField was unset by the workflow
            Assert.False(attributes.ContainsKey(SearchAttributesWorkflow.CustomDoubleField));
        });
    }
}

﻿using Temporalio.Activities;

namespace TemporalioSamples.WorkerSpecificTaskQueues;

public class NormalActivities
{
    private readonly string uniqueWorkerTaskQueue;

    public NormalActivities(string uniqueWorkerTaskQueue) =>
        this.uniqueWorkerTaskQueue = uniqueWorkerTaskQueue;

    [Activity]
#pragma warning disable CA1024
    public string GetUniqueTaskQueue() => uniqueWorkerTaskQueue;
#pragma warning restore CA1024
}

using Microsoft.Extensions.Logging;
using Temporalio.Client;
using Temporalio.Common.EnvConfig;
using Temporalio.Worker;
using TemporalioSamples.WorkerSpecificTaskQueues;

// Create a client to localhost on default namespace
var connectOptions = ClientEnvConfig.LoadClientConnectOptions();
connectOptions.TargetHost ??= "localhost:7233";
connectOptions.LoggerFactory = LoggerFactory.Create(builder =>
    builder.
        AddSimpleConsole(options => options.TimestampFormat = "[HH:mm:ss] ").
        SetMinimumLevel(LogLevel.Information));
var client = await TemporalClient.ConnectAsync(connectOptions);

async Task RunWorkerAsync()
{
    // Cancellation token cancelled on ctrl+c
    using var tokenSource = new CancellationTokenSource();
    Console.CancelKeyPress += (_, eventArgs) =>
    {
        tokenSource.Cancel();
        eventArgs.Cancel = true;
    };

    var uniqueWorkerTaskQueue = Guid.NewGuid().ToString();

    var normalActivities = new NormalActivities(uniqueWorkerTaskQueue);

    // Run worker until cancelled
    Console.WriteLine("Running worker");

    using var normalWorker = new TemporalWorker(
        client,
        new TemporalWorkerOptions(taskQueue: "worker-specific-task-queues-sample")
            .AddActivity(normalActivities.GetUniqueTaskQueue)
            .AddWorkflow<FileProcessingWorkflow>());

    using var uniqueTaskQueueWorker = new TemporalWorker(
        client,
        new TemporalWorkerOptions(taskQueue: uniqueWorkerTaskQueue)
            .AddActivity(WorkerSpecificActivities.DownloadFileToWorkerFileSystemAsync)
            .AddActivity(WorkerSpecificActivities.CleanupFileFromWorkerFileSystemAsync)
            .AddActivity(WorkerSpecificActivities.WorkOnFileInWorkerFileSystemAsync));

    var tasks = new List<Task> { normalWorker.ExecuteAsync(tokenSource.Token), uniqueTaskQueueWorker.ExecuteAsync(tokenSource.Token) };

    var task = await Task.WhenAny(tasks);
    if (task.Exception is not null)
    {
        try
        {
            await tokenSource.CancelAsync();
            await Task.WhenAll(tasks);
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Unhandled ex {ex}");
            throw;
        }
    }
    else
    {
        Console.WriteLine("Worker cancelled");
    }
}

async Task ExecuteWorkflowAsync()
{
    Console.WriteLine("Executing workflow");
    await client.ExecuteWorkflowAsync(
        (FileProcessingWorkflow wf) => wf.RunAsync(5),
        new(id: "file-processing-0", taskQueue: "worker-specific-task-queues-sample"));
}

switch (args.ElementAtOrDefault(0))
{
    case "worker":
        await RunWorkerAsync();
        break;
    case "workflow":
        await ExecuteWorkflowAsync();
        break;
    default:
        throw new ArgumentException("Must pass 'worker' or 'workflow' as the single argument");
}

namespace TemporalioSamples.Tests.WorkerSpecificTaskQueues;

using Temporalio.Activities;
using Temporalio.Client;
using Temporalio.Worker;
using TemporalioSamples.WorkerSpecificTaskQueues;
using Xunit;
using Xunit.Abstractions;

public class FileProcessingWorkflowTests : WorkflowEnvironmentTestBase
{
    public FileProcessingWorkflowTests(ITestOutputHelper output, WorkflowEnvironment env)
        : base(output, env)
    {
    }

    [Fact]
    public async Task RunAsync_SimpleRun_SucceedsAfterRetry()
    {
        var taskQueue = $"tq-{Guid.NewGuid()}";

        // Mock activities
        [Activity("GetUniqueTaskQueue")]
        string MockGetUniqueTaskQueue() => taskQueue;

        [Activity("DownloadFileToWorkerFileSystem")]
        string MockDownloadFileToWorkerFileSystem() => "/path/to/file";

        // We want this to fail the first two times
        var timesCalled = 0;
        [Activity("WorkOnFileInWorkerFileSystem")]
        void MockWorkOnFileInWorkerFileSystem(string path)
        {
            timesCalled++;
            if (timesCalled < 3)
            {
                throw new InvalidOperationException("Intentional failure");
            }
        }

        [Activity("CleanupFileFromWorkerFileSystem")]
        void MockCleanupFileFromWorkerFileSystem(string path)
        {
        }

        using var worker = new TemporalWorker(
            Client,
            new TemporalWorkerOptions(taskQueue).
                AddActivity(MockGetUniqueTaskQueue).
                AddActivity(MockDownloadFileToWorkerFileSystem).
                AddActivity(MockWorkOnFileInWorkerFileSystem).
                AddActivity(MockCleanupFileFromWorkerFileSystem).
                AddWorkflow<FileProcessingWorkflow>());
        await worker.ExecuteAsync(async () =>
        {
            // Just run it to make sure it completes and confirm activity call count is 3
            await Client.ExecuteWorkflowAsync(
                (FileProcessingWorkflow wf) => wf.RunAsync(5),
                new(id: $"wf-{Guid.NewGuid()}", taskQueue: taskQueue));
            Assert.Equal(3, timesCalled);
        });
    }
}

using System.Globalization;
using System.Security.Cryptography;
using System.Text;
using Microsoft.Extensions.Logging;
using Temporalio.Activities;

namespace TemporalioSamples.WorkerSpecificTaskQueues;

public static class WorkerSpecificActivities
{
    [Activity]
#pragma warning disable CA1054
    public static async Task<string> DownloadFileToWorkerFileSystemAsync(string url)
#pragma warning restore CA1054
    {
        var path = Path.GetTempFileName();
        ActivityExecutionContext.Current.Logger.LogInformation("Downloading {Url} and saving to path {Path}", url, path);
        // Here's were the real download code goes.
        var body = Encoding.UTF8.GetBytes("downloaded body");
        await Task.Delay(TimeSpan.FromSeconds(3));
        await File.WriteAllBytesAsync(path, body);
        return path;
    }

    [Activity]
    public static async Task WorkOnFileInWorkerFileSystemAsync(string path)
    {
        var content = await File.ReadAllBytesAsync(path);
        var checksum = ComputeSha256Hash(content);
        await Task.Delay(TimeSpan.FromSeconds(3));
        ActivityExecutionContext.Current.Logger.LogInformation("Did some work on {Path}, checksum: {Checksum}", path, checksum);
    }

    [Activity]
    public static async Task CleanupFileFromWorkerFileSystemAsync(string path)
    {
        await Task.Delay(TimeSpan.FromSeconds(3));
        ActivityExecutionContext.Current.Logger.LogInformation("Removing {Path}", path);
        File.Delete(path);
    }

    private static string ComputeSha256Hash(byte[] input)
    {
        var hash = SHA256.HashData(input);
        var sb = new StringBuilder();
        foreach (var c in hash)
        {
            sb.Append(c.ToString("x2", CultureInfo.InvariantCulture));
        }
        return sb.ToString();
    }
}

using Microsoft.Extensions.Logging;
using Temporalio.Workflows;

namespace TemporalioSamples.WorkerSpecificTaskQueues;

[Workflow]
public class FileProcessingWorkflow
{
    [WorkflowRun]
    public async Task RunAsync(int maxAttempts)
    {
        // When using a worker-specific task queue, if a failure occurs, we want to retry all of the
        // worker-specific logic, so wrap all the logic here in a loop.
        var attempt = 0;
        while (true)
        {
            attempt++;
            try
            {
                await ProcessFileAsync();
                return;
            }
            catch (Exception e)
            {
                // If it's at max attempts, re-throw to fail the workflow
                if (attempt >= maxAttempts)
                {
                    Workflow.Logger.LogError(
                        e,
                        "File processing failed and reached {Attempt} attempts, failing workflow",
                        attempt);
                    throw;
                }
                // Otherwise, just warn and continue
                Workflow.Logger.LogWarning(
                    e,
                    "File processing failed on attempt {Attempt}, trying again",
                    attempt);
            }
        }
    }

    private async Task ProcessFileAsync()
    {
        var uniqueWorkerTaskQueue = await Workflow.ExecuteActivityAsync(
            (NormalActivities act) => act.GetUniqueTaskQueue(),
            new() { StartToCloseTimeout = TimeSpan.FromMinutes(1) });

        var downloadPath = await Workflow.ExecuteActivityAsync(
            () => WorkerSpecificActivities.DownloadFileToWorkerFileSystemAsync("https://temporal.io"),
            new()
            {
                TaskQueue = uniqueWorkerTaskQueue,
                // Note the use of ScheduleToCloseTimeout.
                // The reason this timeout type is used is because this task queue is unique
                // to a single worker. When that worker goes away, there won't be a way for these
                // activities to progress.
                ScheduleToCloseTimeout = TimeSpan.FromMinutes(5),
                HeartbeatTimeout = TimeSpan.FromMinutes(1),
            });

        await Workflow.ExecuteActivityAsync(
            () => WorkerSpecificActivities.WorkOnFileInWorkerFileSystemAsync(downloadPath),
            new()
            {
                TaskQueue = uniqueWorkerTaskQueue,
                ScheduleToCloseTimeout = TimeSpan.FromMinutes(5),
                HeartbeatTimeout = TimeSpan.FromMinutes(1),
            });

        await Workflow.ExecuteActivityAsync(
            () => WorkerSpecificActivities.CleanupFileFromWorkerFileSystemAsync(downloadPath),
            new()
            {
                TaskQueue = uniqueWorkerTaskQueue,
                ScheduleToCloseTimeout = TimeSpan.FromMinutes(5),
                HeartbeatTimeout = TimeSpan.FromMinutes(1),
            });
    }
}

namespace TemporalioSamples.Tests.UpdateWithStartEarlyReturn;

using Temporalio.Activities;
using Temporalio.Client;
using Temporalio.Worker;
using TemporalioSamples.UpdateWithStartEarlyReturn;
using Xunit;
using Xunit.Abstractions;

public class PaymentWorkflowTests : WorkflowEnvironmentTestBase
{
    public PaymentWorkflowTests(ITestOutputHelper output, WorkflowEnvironment env)
        : base(output, env)
    {
    }

    [Fact]
    public async Task RunAsync_Simple_GoesInOrder()
    {
        // Mock activities
        [Activity]
        Task AuthorizePaymentAsync(int amount) => Task.CompletedTask;

        var captureStartedSource = new TaskCompletionSource();
        var captureCompleteSource = new TaskCompletionSource();

        [Activity]
        async Task CapturePaymentAsync()
        {
            captureStartedSource.SetResult();
            await captureCompleteSource.Task;
        }

        // Run worker
        using var worker = new TemporalWorker(
            Client,
            new TemporalWorkerOptions(taskQueue: $"tq-{Guid.NewGuid()}").
                AddActivity(AuthorizePaymentAsync).
                AddActivity(CapturePaymentAsync).
                AddWorkflow<PaymentWorkflow>());
        await worker.ExecuteAsync(async () =>
        {
            // Issue payment, confirm via history update completed after auth but before capture
            var startOperation = WithStartWorkflowOperation.Create(
                (PaymentWorkflow wf) => wf.RunAsync(new(123)),
                new($"wf-{Guid.NewGuid()}", worker.Options.TaskQueue!)
                {
                    IdConflictPolicy = Temporalio.Api.Enums.V1.WorkflowIdConflictPolicy.Fail,
                });
            // Wait for update complete, then confirm authorized and capture started
            await Client.ExecuteUpdateWithStartWorkflowAsync(
                (PaymentWorkflow wf) => wf.WaitUntilAuthorizedAsync(),
                new(startOperation));
            var handle = await startOperation.GetHandleAsync();
            await captureStartedSource.Task;
            Assert.True(await handle.QueryAsync(wf => wf.Authorized));

            // Now complete capture
            captureCompleteSource.SetResult();
            await handle.GetResultAsync();
        });
    }
}
